declare @partitionKey nvarchar(4000), @l int, @firstItem varchar(128), @lastItem varchar(128)

select @firstItem = @@firstItem, @lastItem = @@lastItem, @partitionKey = 'convert(char(8), m.ngay_ct, 112) + m.so_ct + m.stt_rec + replace(str(a.line_nbr, 5), '' '', ''0'')'
select @l = 21 + character_maximum_length from information_schema.columns where table_name = 'wrkcolumns' and column_name = 'so_ct'

if @firstItem <> '' set @firstItem = left(@firstItem, @l) + replace(str(right(@firstItem, len(@firstItem) - @l), 5), ' ', '0')
if @lastItem <> '' set @lastItem = left(@LastItem, @l) + replace(str(right(@lastItem, len(@lastItem) - @l), 5), ' ', '0')

exec FastBusiness$Partition$ExecutePage @@refresh, @@pageIndex, @@pageCount, @@lastPage, @@lastCount, @FirstItem, @LastItem, @@textExternal, @queryFormClause, @queryWhereClause, @@textOrderBy, @partitionKey, 'm.ngay_ct', @ngay_ct1, @ngay_ct2, @ma_dvcs, @@admin, @@userID

function init$ZDNZBTFilter$(f) {f.getItem('so_ct')._idle = 9;}
function active$ZDNZBTFilter$(f) {
  f._looking = f.getItem('so_ct')._controlBehavior;
  f._looking.add_loading(on$ZDNZBTFilter$Before$Loading);
  
  var g = f.grid, w = g.get_element().parentForm, d2 = w.getItemValue('ngay_lct'), u = w.getItemValue('ma_dvcs');
  g._custID = w.getItemValue('ma_kh');
  g._custName = w.getItemValue('ten_kh%l');
  f.setItemValues('ngay_ct2, ma_kh, ma_dvcs', [d2, g._custID, u]);
}
function close$ZDNZBTFilter$(f) {try {f._looking.remove_loading(on$ZDNZBTFilter$Before$Loading);} catch (ex) {}}
function on$ZDNZBTFilter$Before$Loading(sender, e) {
  var f = sender._element.parentForm;
  if (!f.validFields('ngay_ct1')) e.type.cancelEvent = true;
  else {
    var g = f.grid, w = g.get_element().parentForm;
    var d1 = f.getItemValue('ngay_ct1'), d2 = w.getItemValue('ngay_lct'), u = w.getItemValue('ma_dvcs');    

    a = [
      {Name: 'ngay_ct1', Type: 'DateTime', Value: d1}, 
      {Name: 'ngay_ct2', Type: 'DateTime', Value: d2},
      {Name: 'ma_kh', Type: 'String', Value: g._custID},
      {Name: 'ma_dvcs', Type: 'String', Value: u}
    ];
    sender.set_memvars(a);
  }
}
function on$ZDNZBTFilter$Retrieve$QueryComplete(f, c, d, k, e, h, l) {
  var g = f.grid;
  if (c != '') {
    g._voucher$Retrieve$ID = d;
    g._voucher$Retrieve$Number = c;
    g._voucher$Retrieve$Fields = k;
    g._voucher$Retrieve$Date = $func.formatStringToDate(e);
  } else {
    g._filter$Fields = l;
  }
  set$ZDNZBTFilter$FormScript(g, h);
}
function set$ZDNZBTFilter$FormScript(g, h) {g._formScript = 'show$ZDNZBTFilter$QueryComplete(this,\'' + (h ? h : '') + '\')';}
function show$ZDNZBTFilter$QueryComplete(g, h) {
  if (h != '') {
    g.showForm(h);
  } else {
    g.showForm('ZDNZBTForm');
  }
  g._memvars = [];
}
